#include <deque>
#include <iostream>

int main() {
    std::deque<int> d;

    // O(1) amortized insertion at the back
    d.push_back(10);

    // O(1) amortized insertion at the front (Vector would be O(N))
    d.push_front(5);

    // O(1) removal from the front
    d.pop_front();

    std::cout << d.front() << "\n"; // Output: 10

    return 0;
}
